    input reset,
    input ped,
    output reg [1:0] light,
    output reg walk
);

    reg [2:0] state;
    reg [3:0] count;

    always @(posedge clk) begin
        if (reset) begin
            state <= 3'd0;
            count <= 4'd0;
            light <= 2'b00;
            walk <= 1'b1;
        end else begin
            case (state)
                3'd0: begin // RED
                    if (count == 3'd3) begin
                        state <= 3'd1;
                        count <= 4'd0;
                    end else begin
                        count <= count + 1;
                    end
                end
                3'd1: begin // GREEN
                    if (ped) begin
                        state <= 3'd2;
                        count <= 4'd0;
                    end else begin
                        if (count == 3'd4) begin
                            state <= 3'd2;
                            count <= 4'd0;
                        end else begin
                            count <= count + 1;
                        end
                    end
                end
                3'd2: begin // YELLOW
                    if (count == 3'd2) begin
                        state <= 3'd0;
                        count <= 4'd0;
                    end else begin
                        count <= count + 1;
                    end
                end
                3'd3: begin // RED (from pedestrian)
                    if (count == 3'd3) begin
                        state <= 3'd1;
                        count <= 4'd0;
                    end else begin
                        count <= count + 1;
                    end
                end
            endcase
        end
    end

    always @(posedge clk) begin
        if (reset) begin
            light <= 2'b00;
            walk <= 1'b1;
        end else begin
            case (state)
                3'd0: begin
                    light <= 2'b00;
                    walk <= 1'b1;
                end
                3'd1: begin
                    light <= 2'b01;
                    walk <= 1'b0;
                end
                3'd2: begin
                    light <= 2'b10;
                    walk <= 1'b0;
                end
                3'd3: begin
                    light <= 2'b00;
                    walk <= 1'b1;
                end
            endcase
        end
    end

endmodule

